class CuentaAtras:
    def __init__(self, n):
        self.actual = n
    def __iter__(self):
        return self
    def __next__(self):
        if self.actual <= 0:
            raise StopIteration
        valor = self.actual
        self.actual -= 1
        return valor
print(list(CuentaAtras(int(input()))))

