import json
datos = json.loads(input())
def resolver(opciones):
    elegidos = []
    usados = set()
    def buscar(posicion):
        if posicion == len(opciones):
            return elegidos.copy()
        for candidato in opciones[posicion]:
            if candidato in usados:
                continue
            elegidos.append(candidato)
            usados.add(candidato)
            solucion = buscar(posicion + 1)
            if solucion is not None:
                return solucion
            usados.remove(candidato)
            elegidos.pop()
        return None
    return buscar(0)
print(resolver(datos))

