import json
datos = json.loads(input())
class Biblioteca:
    def __init__(self, libros):
        self.catalogo = set(libros)
        self.disponibles = set(libros)
    def actuar(self, accion, titulo):
        if accion == "prestar" and titulo in self.disponibles:
            self.disponibles.remove(titulo)
            return "OK"
        if accion == "devolver" and titulo in self.catalogo and titulo not in self.disponibles:
            self.disponibles.add(titulo)
            return "OK"
        return "NO"
b = Biblioteca(datos["libros"])
for accion, titulo in datos["acciones"]:
    print(b.actuar(accion, titulo))
print(sorted(b.disponibles))
